from pathlib import Path
from dataclasses import replace
import sys,json,time,traceback,collections
R=Path.cwd();D=R/'.local_agent/no-progress-context-20261017';N=D/'next-evaluator';sys.path[:0]=[str(R)]
from generic_chess.rules.serialization import deserialize_ruleset
from generic_chess.rules.compiler import compile_semantic_ruleset
from generic_chess.ai.evaluation.semantic import build_semantic_opportunity_profile
from generic_chess.ai.evaluation.semantic_attacks import SemanticAttackEvaluator
from generic_chess.ai.evaluation.config import EvaluationConfig
from generic_chess.ai.alphabeta.player import AlphaBetaPlayer
from generic_chess.ai.limits import SearchLimits
from generic_chess.session.session import GameSession
from generic_chess.core.actions import SemanticBoardMove,SemanticDropMove,PassAction
from generic_chess.core.coordinates import Square
from scripts.research_record import record_value
from tools.local_agent.common import write_json
cfg=replace(EvaluationConfig(),dynamic_mobility_weight=0,anchor_escape_weight=0,promotion_potential_weight=0);inputs=[z for z in json.loads((D/'product-policy-axis-inputs.json').read_bytes())if z['axis']==2];receipts=json.loads((D/'product-policy-axis-results.json').read_bytes())['rows'];rows=[];stats=collections.Counter();start=time.perf_counter()
def decode(a):
 if not a:return PassAction()
 if 'from_square'in a:return SemanticBoardMove(a['pattern_id'],a['geometry_id'],a['actor_type_id'],Square(**a['from_square']),Square(**a['to_square']),a['promotion_target_id'])
 return SemanticDropMove(a['pattern_id'],a['geometry_id'],a['base_type_id'],Square(**a['to_square']))
def material(state,profile):
 side=state.position.side_to_move;v=sum((1 if p.owner==side else -1)*profile.board_value_by_type[p.current_type_id]for p in state.position.board if p is not None)
 return v+sum((1 if owner==side else -1)*profile.hand_value_by_base_type[t]*n for owner,hand in enumerate(state.position.hands)for t,n in hand.counts)
for z in inputs:
 assert time.perf_counter()-start<120
 for name in('rollout','advisor','slack'):
  f=json.loads((R/'.local_agent'/f'{name}.json').read_bytes());assert not f.get('stopped')and not f.get('user_paused')
 c=replace(compile_semantic_ruleset(deserialize_ruleset(json.dumps(z['rule']))),_legacy_compiled=None);profile,scope=build_semantic_opportunity_profile(c,cfg);ev=SemanticAttackEvaluator(c,profile,cfg,backend='core');session=GameSession(c);before=session.state;t=time.perf_counter()
 try:
  player=AlphaBetaPlayer(c,evaluator_override=ev,use_disk_cache=False,use_native_semantic_legality=False);v=player.choose_action(session,SearchLimits(max_depth=1,max_nodes=1024,max_time_seconds=2,quiescence_max_depth=0,quiescence_hard_max_depth=0));assert v.action in session.legal_actions()and v.completed_depth==1 and session.state is before
  row={'family':z['family'],'status':'returned','seconds':time.perf_counter()-t,'decision':record_value(v),'profile':record_value(profile),'projection_scope':scope,'normal_source_unmodified':True}
 except Exception as e:row={'family':z['family'],'status':'error','error':{'type':type(e).__name__,'message':str(e),'trace':traceback.format_exc()}}
 # Replay actual saved axis2 branches, not deserialize a reduced Position.
 for rr in [r for r in receipts if r['family']==z['family']and r['axis']==2]:
  s=GameSession(c);branches=collections.defaultdict(list)
  for b in rr['all_branch_receipts']:branches[b['parent_ply']].append(b)
  for a in rr['actions']:
   for b in branches[s.state.ply_count]:
    from copy import copy
    child=copy(s);child.submit(decode(b['action']));assert record_value(child.state)==b['child'];assert ev.evaluate(child.state)==material(child.state,profile);stats['actual_branch_material_checks']+=1
   s.submit(decode(a));assert ev.evaluate(s.state)==material(s.state,profile);stats['actual_chosen_material_checks']+=1
 rows.append(row);print(z['family'],row['status'],flush=True)
write_json(N/'results.json',{'complete':len(rows)==12,'errors':sum(x['status']=='error'for x in rows),'rows':rows,'stats':dict(stats),'seconds':time.perf_counter()-start,'conclusion':'Existing explicit zero-dynamic semantic profile/evaluator works without metadata implementation changes. Projection still excludes mechanisms and retains unvalidated hand/promotion constants; no new metric price, default promotion, training or AUX helper.'})
print('DONE',dict(stats),flush=True)
